@startuml

enum PriorityScore {
  High
  Low
}

class Patient {
  + FirstName : string
  + LastName : string
  + PhoneNumber : string
  + ConsentSigned : boolean
}

abstract class Doctor {
  + IdNumber : int
  + Signature : string
}

class HeadDoctor extends Doctor {}

class Treatment {
  + Stage : int
  + AppliedDate : date
}

class Diagnosis {
  + PriorityScore : PriorityScore
}

class TreatmentPlan {
  + Description : string
}

class Illness {
  + Name : string
  + PriorityScore : PriorityScore
}

Patient "1" -- "*" Doctor
Doctor "0..*" -- "*" Diagnosis
Diagnosis "1" -- "1" Treatment
Treatment "1" -- "0..1" TreatmentPlan
Illness "1" -- "*" Diagnosis

HeadDoctor "1" -- "*" Diagnosis

@enduml

